#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <ctype.h>

#define MAX_HEADER 4096
#define MAX_SESSIONS 64

typedef struct {
    char session_id[33];
    char username[64];
    int privilege_level;
    unsigned long expires;
} session_t;

static session_t g_sessions[MAX_SESSIONS];
static int g_session_count = 0;

/* Base64 decode table */
static const unsigned char b64_table[256] = {
    ['A']=0,['B']=1,['C']=2,['D']=3,['E']=4,['F']=5,['G']=6,['H']=7,
    ['I']=8,['J']=9,['K']=10,['L']=11,['M']=12,['N']=13,['O']=14,['P']=15,
    ['Q']=16,['R']=17,['S']=18,['T']=19,['U']=20,['V']=21,['W']=22,['X']=23,
    ['Y']=24,['Z']=25,['a']=26,['b']=27,['c']=28,['d']=29,['e']=30,['f']=31,
    ['g']=32,['h']=33,['i']=34,['j']=35,['k']=36,['l']=37,['m']=38,['n']=39,
    ['o']=40,['p']=41,['q']=42,['r']=43,['s']=44,['t']=45,['u']=46,['v']=47,
    ['w']=48,['x']=49,['y']=50,['z']=51,['0']=52,['1']=53,['2']=54,['3']=55,
    ['4']=56,['5']=57,['6']=58,['7']=59,['8']=60,['9']=61,['+']=62,['/']=63
};

/* Decode base64 input into output buffer. Returns decoded length.
 * Caller must ensure outbuf is at least (inlen/4)*3 bytes. */
static int base64_decode(const char *input, int inlen, unsigned char *outbuf, int outbuf_size) {
    int i, j = 0;
    unsigned char a, b, c, d;
    int pad = 0;

    /* Strip trailing padding for length calculation */
    if (inlen > 0 && input[inlen-1] == '=') pad++;
    if (inlen > 1 && input[inlen-2] == '=') pad++;

    for (i = 0; i < inlen && j < outbuf_size - 2; i += 4) {
        a = b64_table[(unsigned char)input[i]];
        b = (i+1 < inlen) ? b64_table[(unsigned char)input[i+1]] : 0;
        c = (i+2 < inlen) ? b64_table[(unsigned char)input[i+2]] : 0;
        d = (i+3 < inlen) ? b64_table[(unsigned char)input[i+3]] : 0;

        if (j < outbuf_size) outbuf[j++] = (a << 2) | (b >> 4);
        if (j < outbuf_size) outbuf[j++] = (b << 4) | (c >> 2);
        if (j < outbuf_size) outbuf[j++] = (c << 6) | d;
    }
    /* Adjust for padding */
    j -= pad;
    if (j < 0) j = 0;
    return j;
}

/* Validate that a string contains only hex characters */
static int is_valid_hex(const char *s, int len) {
    for (int i = 0; i < len; i++) {
        if (!isxdigit((unsigned char)s[i])) return 0;
    }
    return 1;
}

/* Lookup session by ID - returns pointer or NULL */
static session_t *find_session(const char *sid) {
    if (!sid || strlen(sid) != 32 || !is_valid_hex(sid, 32)) return NULL;
    for (int i = 0; i < g_session_count; i++) {
        if (memcmp(g_sessions[i].session_id, sid, 32) == 0)
            return &g_sessions[i];
    }
    return NULL;
}

/* Parse Authorization header value.
 * Format: "Basic <base64(username:password)>" or "Bearer <session_id>"
 * Returns 1 if authenticated, 0 otherwise. */
static int check_auth(const char *auth_value, char *out_user, int out_user_size) {
    if (strncmp(auth_value, "Bearer ", 7) == 0) {
        const char *token = auth_value + 7;
        session_t *sess = find_session(token);
        if (sess && sess->privilege_level >= 1) {
            strncpy(out_user, sess->username, out_user_size - 1);
            out_user[out_user_size - 1] = '\0';
            return 1;
        }
        return 0;
    }

    if (strncmp(auth_value, "Basic ", 6) == 0) {
        const char *encoded = auth_value + 6;
        int elen = strlen(encoded);
        /* Calculate decoded size: every 4 base64 chars = 3 bytes */
        int decoded_max = ((elen + 3) / 4) * 3 + 1; /* +1 for safety */
        char *decoded = (char *)malloc(decoded_max);
        if (!decoded) return 0;

        int dlen = base64_decode(encoded, elen, (unsigned char *)decoded, decoded_max);
        if (dlen <= 0 || dlen >= decoded_max) {
            free(decoded);
            return 0;
        }
        decoded[dlen] = '\0';

        /* Find colon separator */
        char *colon = memchr(decoded, ':', dlen);
        if (colon) {
            int ulen = colon - decoded;
            if (ulen > 0 && ulen < out_user_size) {
                memcpy(out_user, decoded, ulen);
                out_user[ulen] = '\0';
                free(decoded);
                return 1; /* Simplified: accept any basic auth */
            }
        }
        free(decoded);
        return 0;
    }
    return 0;
}

/* Parse Content-Length from headers */
static int parse_content_length(const char *headers) {
    const char *cl = strcasestr(headers, "Content-Length:");
    if (!cl) return 0;
    cl += 15;
    while (*cl == ' ') cl++;
    int val = atoi(cl);
    if (val < 0 || val > 8192) return -1;
    return val;
}

/* Sanitize a JSON string value to prevent injection */
static void sanitize_json_value(const char *input, int input_len, char *output, int output_size) {
    int j = 0;
    for (int i = 0; i < input_len && j < output_size - 2; i++) {
        unsigned char ch = (unsigned char)input[i];
        if (ch == '"') {
            output[j++] = '\\'; output[j++] = '"';
        } else if (ch == '\\') {
            output[j++] = '\\'; output[j++] = '\\';
        } else if (ch == '\n') {
            output[j++] = '\\'; output[j++] = 'n';
        } else if (ch == '\r') {
            output[j++] = '\\'; output[j++] = 'r';
        } else if (ch >= 0x20 && ch < 0x7f) {
            output[j++] = ch;
        }
        /* Drop non-printable/non-ASCII characters */
    }
    output[j] = '\0';
}

/* Process an API request to update user profile.
 * Expects JSON body like: {"display_name": "...", "bio": "..."} */
static void handle_profile_update(int fd, const char *body, int body_len, const char *username) {
    /* Simple JSON field extraction - find display_name value */
    const char *dn_key = "\"display_name\"";
    const char *dn_pos = memmem(body, body_len, dn_key, strlen(dn_key));

    char display_name_raw[128];
    char display_name[256];
    memset(display_name_raw, 0, sizeof(display_name_raw));
    memset(display_name, 0, sizeof(display_name));

    if (dn_pos) {
        /* Skip to the value */
        const char *val_start = dn_pos + strlen(dn_key);
        while (val_start < body + body_len && (*val_start == ':' || *val_start == ' ' || *val_start == '"'))
            val_start++;
        const char *val_end = val_start;
        while (val_end < body + body_len && *val_end != '"')
            val_end++;

        int vlen = val_end - val_start;
        if (vlen > 0 && vlen < (int)sizeof(display_name_raw)) {
            memcpy(display_name_raw, val_start, vlen);
            sanitize_json_value(display_name_raw, vlen, display_name, sizeof(display_name));
        }
    }

    /* Sanitize username for JSON output */
    char safe_username[128];
    sanitize_json_value(username, strlen(username), safe_username, sizeof(safe_username));

    /* Build response */
    char response[512];
    int rlen = snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n"
        "{\"status\":\"updated\",\"user\":\"%s\",\"display_name\":\"%s\"}",
        safe_username, display_name);
    if (rlen > 0 && rlen < (int)sizeof(response))
        write(fd, response, rlen);
}

/* Read and process a single HTTP request */
static void handle_connection(int fd) {
    char raw[MAX_HEADER + 8192];
    memset(raw, 0, sizeof(raw));

    int total = 0;
    int header_end = -1;

    /* Read until we have full headers */
    while (total < (int)sizeof(raw) - 1) {
        int n = read(fd, raw + total, sizeof(raw) - 1 - total);
        if (n <= 0) break;
        total += n;

        /* Check for end of headers */
        char *hdr_end = strstr(raw, "\r\n\r\n");
        if (hdr_end) {
            header_end = hdr_end - raw + 4;
            break;
        }
    }

    if (header_end < 0) {
        const char *err = "HTTP/1.1 400 Bad Request\r\n\r\n";
        write(fd, err, strlen(err));
        return;
    }

    /* Parse method and path */
    char method[16] = {0};
    char path[256] = {0};
    sscanf(raw, "%15s %255s", method, path);

    /* Extract Authorization header */
    char auth_user[64] = {0};
    int authenticated = 0;
    const char *auth_hdr = strcasestr(raw, "Authorization:");
    if (auth_hdr) {
        auth_hdr += 14;
        while (*auth_hdr == ' ') auth_hdr++;
        char auth_val[512] = {0};
        int ai = 0;
        while (auth_hdr[ai] && auth_hdr[ai] != '\r' && auth_hdr[ai] != '\n' && ai < 511) {
            auth_val[ai] = auth_hdr[ai];
            ai++;
        }
        authenticated = check_auth(auth_val, auth_user, sizeof(auth_user));
    }

    /* Route: POST /api/profile requires auth */
    if (strcmp(method, "POST") == 0 && strcmp(path, "/api/profile") == 0) {
        if (!authenticated) {
            const char *err = "HTTP/1.1 401 Unauthorized\r\n\r\n";
            write(fd, err, strlen(err));
            return;
        }

        int content_length = parse_content_length(raw);
        if (content_length < 0) {
            const char *err = "HTTP/1.1 400 Bad Request\r\n\r\n";
            write(fd, err, strlen(err));
            return;
        }

        /* Read remaining body if needed */
        int body_received = total - header_end;
        while (body_received < content_length && total < (int)sizeof(raw) - 1) {
            int n = read(fd, raw + total, sizeof(raw) - 1 - total);
            if (n <= 0) break;
            total += n;
            body_received = total - header_end;
        }

        handle_profile_update(fd, raw + header_end, body_received, auth_user);
    } else {
        const char *resp = "HTTP/1.1 404 Not Found\r\n\r\n";
        write(fd, resp, strlen(resp));
    }
}

int main(void) {
    int srv = socket(AF_INET, SOCK_STREAM, 0);
    if (srv < 0) return 1;

    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(9090);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(srv, (struct sockaddr *)&addr, sizeof(addr)) < 0) return 1;
    if (listen(srv, 16) < 0) return 1;

    while (1) {
        int fd = accept(srv, NULL, NULL);
        if (fd < 0) continue;
        handle_connection(fd);
        close(fd);
    }
    return 0;
}
